SELECT 'датчик «code-line» ' || fact_gap($1, 'code-line') || ': проверить нечем, и это не зелёное' AS detail WHERE NOT fact_fresh($1, 'code-line') UNION ALL SELECT 'датчик строк ' || fact_gap($1, 'code-line') || ': сходится ли адрес — неизвестно' AS detail WHERE NOT EXISTS (SELECT 1 FROM code_fact WHERE project_id = $1 AND kind = 'code-line') UNION ALL SELECT a.entity_kind || ' ' || coalesce(nullif(a.entity_name, ''), '(одиночный)') || ' — ' || a.path || ':' || a.line || ': ' || CASE WHEN f.name IS NULL THEN 'строка не снята датчиком' WHEN f.detail LIKE 'файла нет%' OR f.detail LIKE 'в файле строк%' OR f.detail LIKE 'имя неоднозначно%' THEN f.detail WHEN a.anchor <> '' AND position(a.anchor in f.detail) = 0 THEN 'якорь «' || a.anchor || '» уехал, там теперь «' || f.detail || '»' ELSE 'сходится' END AS detail FROM project_code_address a LEFT JOIN code_fact f ON f.project_id = a.project_id AND f.kind = 'code-line' AND f.name = a.path || ':' || a.line WHERE a.project_id = $1 AND EXISTS (SELECT 1 FROM code_fact WHERE project_id = $1 AND kind = 'code-line') AND (f.name IS NULL OR f.detail LIKE 'файла нет%' OR f.detail LIKE 'в файле строк%' OR f.detail LIKE 'имя неоднозначно%' OR (a.anchor <> '' AND position(a.anchor in f.detail) = 0)) ORDER BY 1
